window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-26ec9e9988606b5b"]={"versions": [{"id": "FIG-26ec9e9988606b5b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Paketdiagramm zur Veranschaulichung des logischen Aufbaus und der Signierungs- bzw. Kapselungshierarchie eines AUTOSAR Adaptive Vehicle Package im Kontext des Update and Configuration Management (UCM). Dargestellt wird die Beziehung zwischen einem zentralen Vehicle Package und den darin referenzierten fahrzeugweiten Software Packages (<code>Software Package A</code> und <code>Software Package B</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Artefakte:</p>\n<ul class=\"fig-list\"><li><strong>Vehicle Package</strong>: Äußerer Container mit einem <code>OEM authentication tag</code>.\n<ul class=\"fig-list\"><li>Enthält einen inneren <code>Signed container</code>, der wiederum aus folgenden Dokumenten besteht:\n<ul class=\"fig-list\"><li><code>Vehicle Package manifest</code>\n</li><li><code>Software Package manifest A</code> (referenziert über Pfeil das Manifest in Software Package A)\n</li><li><code>Software Package manifest B</code> (referenziert über Pfeil das Manifest in Software Package B)\n</li></ul>\n</li></ul>\n</li><li><strong>Software Package A &amp; B</strong>: Eigenständige Software-Pakete mit jeweils folgendem Aufbau:\n<ul class=\"fig-list\"><li>Äußerer <code>Signed container</code> gesichert durch einen <code>Authentication tag</code> auf Paketebene.\n</li><li><code>Software Package Manifest</code> auf oberster Paketebene.\n</li><li>Eingebettetes <code>SoftwareCluster A</code> bzw. <code>SoftwareCluster B</code>, gekapselt in einen weiteren inneren <code>Signed container</code> mit eigenem <code>Authentication tag</code>.\n</li><li>SoftwareCluster-Inhalt: <code>Executables</code>, <code>Data</code>, <code>Manifests</code> sowie ein <code>Software Cluster Manifest</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Assoziation und Integritätsprüfung:</p>\n<ol class=\"fig-list\"><li>Das Vehicle Package transportiert die Manifeste der beteiligten Software Packages gebündelt in einem gemeinsamen signierten Container.\n</li><li>Pfeilverbindungen verdeutlichen die 1:1-Entsprechung bzw. Zuordnung von <code>Software Package manifest A</code> und <code>Software Package manifest B</code> aus dem zentralen Vehicle Package zu den dezentralen <code>Software Package Manifest</code>-Artefakten der jeweiligen Software-Pakete A und B.\n</li><li>Mehrstufige Absicherung über kryptografische Signaturen/Tags (<code>OEM authentication tag</code> für das Gesamtfahrzeug-Paket, <code>Authentication tag</code> für jedes Software Package sowie für jeden einzelnen SoftwareCluster-Container).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für UCM Master und UCM Subordinate zur Strukturierung von Update-Kampagnen auf Gesamtfahrzeugebene:</p>\n<ul class=\"fig-list\"><li>Ein Vehicle Package kapselt die aggregierten Manifeste aller zu aktualisierenden Software Packages in einem gemeinsamen <code>Signed container</code>.\n</li><li>Software Packages besitzen eine geschachtelte Signaturstruktur, bei der Cluster-Inhalte (<code>SoftwareCluster</code>) und Paketmetadaten (<code>Software Package Manifest</code>) getrennt signiert und geschützt vorliegen.\n</li><li>Entwickler von UCM- und OTA-Systemen müssen die mehrstufige Validierung (OEM-Authentifizierung des Vehicle Package gefolgt von der Integritätsprüfung der individuellen Software Packages und Cluster) implementieren.\n</li></ul>"}, {"id": "FIG-51d8ec7b11758dda", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Paketdiagramm zur Veranschaulichung des logischen Aufbaus und der Signierungs- bzw. Kapselungshierarchie eines AUTOSAR Adaptive Vehicle Package im Kontext des Update and Configuration Management (UCM). Dargestellt wird die Beziehung zwischen einem zentralen Vehicle Package und den darin referenzierten fahrzeugweiten Software Packages (<code>Software Package A</code> und <code>Software Package B</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Artefakte:</p>\n<ul class=\"fig-list\"><li><strong>Vehicle Package</strong>: Äußerer Container mit einem <code>OEM authentication tag</code>.\n<ul class=\"fig-list\"><li>Enthält ein inneres <code>Signed ARXML file</code>, das aus folgenden Dokumenten besteht:\n<ul class=\"fig-list\"><li><code>Vehicle Package manifest</code>\n</li><li><code>Software Package manifest A</code> (referenziert über Pfeil das Manifest in Software Package A)\n</li><li><code>Software Package manifest B</code> (referenziert über Pfeil das Manifest in Software Package B)\n</li></ul>\n</li></ul>\n</li><li><strong>Software Package A &amp; B</strong>: Eigenständige Software-Pakete mit jeweils folgendem Aufbau:\n<ul class=\"fig-list\"><li>Äußerer <code>Signed container</code> gesichert durch einen <code>Authentication tag</code> auf Paketebene.\n</li><li><code>Software Package Manifest</code> auf oberster Paketebene.\n</li><li>Eingebettetes <code>SoftwareCluster A</code> bzw. <code>SoftwareCluster B</code>, gekapselt in einen weiteren inneren <code>Signed container</code> mit eigenem <code>Authentication tag</code>.\n</li><li>SoftwareCluster-Inhalt: <code>Executables</code>, <code>Data</code>, <code>Manifests</code> sowie ein <code>Software Cluster Manifest</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Assoziation und Integritätsprüfung:</p>\n<ol class=\"fig-list\"><li>Das Vehicle Package transportiert die Manifeste der beteiligten Software Packages gebündelt in einem gemeinsamen signierten Container.\n</li><li>Pfeilverbindungen verdeutlichen die 1:1-Entsprechung bzw. Zuordnung von <code>Software Package manifest A</code> und <code>Software Package manifest B</code> aus dem zentralen Vehicle Package zu den dezentralen <code>Software Package Manifest</code>-Artefakten der jeweiligen Software-Pakete A und B.\n</li><li>Mehrstufige Absicherung über kryptografische Signaturen/Tags (<code>OEM authentication tag</code> für das Gesamtfahrzeug-Paket, <code>Authentication tag</code> für jedes Software Package sowie für jeden einzelnen SoftwareCluster-Container).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für UCM Master und UCM Subordinate zur Strukturierung von Update-Kampagnen auf Gesamtfahrzeugebene:</p>\n<ul class=\"fig-list\"><li>Ein Vehicle Package bündelt das <code>Vehicle Package manifest</code> sowie die Manifeste aller beteiligten Software Packages in einer gemeinsamen signierten ARXML-Datei (<code>Signed ARXML file</code>).\n</li><li>Software Packages besitzen eine geschachtelte Signaturstruktur, bei der Cluster-Inhalte (<code>SoftwareCluster</code>) und Paketmetadaten (<code>Software Package Manifest</code>) getrennt signiert und geschützt vorliegen.\n</li><li>Entwickler von UCM- und OTA-Systemen müssen die mehrstufige Validierung (OEM-Authentifizierung des Vehicle Package, ARXML-Signaturprüfung der Manifeste sowie Integritätsprüfung der individuellen Software Packages und Cluster) implementieren.\n</li></ul>"}], "trans": [{"from": "FIG-26ec9e9988606b5b", "to": "FIG-51d8ec7b11758dda", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Artefakt-Typ im Vehicle Package: Das innere signierte Element, welches das <code>Vehicle Package manifest</code> sowie <code>Software Package manifest A</code> und <code>Software Package manifest B</code> bündelt, ist von <code>Signed container</code> zu <code>Signed ARXML file</code> umdefiniert.\n</li><li>Header-Bereich: Die versehentlich im Bildausschnitt enthaltene Spezifikationsanforderung <code>[SWS_UCM_01269]{DRAFT} Campaign cancellation history</code> nebst Abschnittsüberschrift <code>7.2.11 Content of Vehicle Package</code> wurde entfernt.\n</li></ul>"}]};
